package dev.veltraph.client.inventory.bottle;
import org.junit.jupiter.api.Test;
import java.util.*;
import dev.veltraph.client.inventory.bottle.BottleFillWorkflow.Stack;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.inventory.bottle.BottleFillWorkflow.*;

class BottleFillBatchTest {
    static class ServerPort extends BottleFillWorkflowTest.Port {
        boolean nativeFill=true,sameMenuStore;int sourceApproaches,chestApproaches;
        ServerPort(){var tool=inventory.get(2);inventory=new ArrayList<>(Collections.nCopies(36,Stack.EMPTY));inventory.set(2,tool);for(int i:new int[]{0,1,3,4,5})inventory.set(i,new Stack(BottleFillWorkflowTest.GLASS,64,false));inventory.set(15,new Stack(new Identity("minecraft:diamond","Diamond","[diamond]"),2,false));}
        @Override public Approach approach(Observation o,Position target,Position stand){if(target.equals(request(1).source()))sourceApproaches++;else chestApproaches++;return super.approach(o,target,stand);}
        public boolean fillAcknowledged(Observation o,List<Stack> before,List<Stack> after){return nativeFill;}
        public boolean storageAcknowledged(Observation o,List<Stack> after,List<Stack> chestBefore,int output){return sameMenuStore&&acceptStore;}
    }
    static Request request(int quantity){var r=BottleFillWorkflowTest.request(quantity);return new Request(r.glass(),r.water(),quantity,r.dimension(),r.source(),r.sourceStand(),r.chest(),r.chestStand(),r.chestTitle(),1,500);}
    static void drive(BottleFillWorkflow w,int n){for(int tick=1;tick<=n&&w.active();tick++)w.tick(tick);}
    @Test void firstAcceptedConversionContinuesCollectionUntilReserveOrQuota(){var p=new ServerPort();var w=new BottleFillWorkflow(p);w.startBatched(request(27),0,0,3);for(int t=1;t<20&&p.uses<1;t++)w.tick(t);for(int t=20;t<25&&w.state()==State.WAIT_FILL;t++)w.tick(t);assertEquals(State.WATER,w.state(),w.reason());assertEquals(0,p.opens);assertEquals(1,p.uses);}
    @Test void strictReserve3AllowsOneLastConversionThenDrains27BeforeAnotherSourceTrip(){var p=new ServerPort();var w=new BottleFillWorkflow(p);w.startBatched(request(27),0,0,3);for(int t=1;t<500&&w.state()!=State.CHEST;t++)w.tick(t);assertEquals(State.CHEST,w.state());assertEquals(27,p.uses);assertEquals(2,p.inventory.stream().filter(Stack::empty).count());assertEquals(0,p.opens);drive(w,1000);assertEquals(State.COMPLETE,w.state(),w.reason());assertEquals(27,p.stores);assertEquals(27,w.completed());assertEquals(37,p.inventory.get(0).count());for(int i:new int[]{1,3,4,5})assertEquals(64,p.inventory.get(i).count());assertEquals(2,p.selected);}
    @Test void strictReserve2KeepsCollectingUntilOneFreeCellThenStops(){var p=new ServerPort();p.chest=new ArrayList<>(Collections.nCopies(54,Stack.EMPTY));var w=new BottleFillWorkflow(p);w.startBatched(request(28),0,0,2);for(int t=1;t<500&&w.state()!=State.CHEST;t++)w.tick(t);assertEquals(State.CHEST,w.state());assertEquals(28,p.uses);assertEquals(1,p.inventory.stream().filter(Stack::empty).count());assertEquals(0,p.opens);}
    @Test void clientPredictionNeverAllowsSecondFillOrChestUntilActualFillReceipt(){var p=new ServerPort();p.nativeFill=false;var w=new BottleFillWorkflow(p);w.startBatched(request(3),0,0,3);drive(w,100);assertEquals(State.WAIT_FILL,w.state());assertEquals(1,p.uses);assertEquals(0,p.opens);assertEquals(0,p.stores);}
    @Test void foreignProtectedDeltaStopsTheBatchBeforeChest(){var p=new ServerPort();var w=new BottleFillWorkflow(p);w.startBatched(request(3),0,0,3);for(int t=1;t<30&&w.state()!=State.WAIT_FILL;t++)w.tick(t);p.inventory.set(15,Stack.EMPTY);w.tick(31);assertEquals(State.RECOVERY_REQUIRED,w.state());assertEquals(1,p.uses);assertEquals(0,p.opens);}
    @Test void exactSameMenuReceiptsDrainThenRequireFreshFinalBatchVerification(){var p=new ServerPort();p.sameMenuStore=true;var w=new BottleFillWorkflow(p);w.startBatched(request(3),0,0,3);drive(w,300);assertEquals(State.COMPLETE,w.state(),w.reason());assertEquals(3,p.uses);assertEquals(3,p.stores);assertEquals(2,p.opens,"one batch opening plus final fresh verification");assertEquals(3,w.completed());}
    @Test void silentPredictedStoresUseFreshReopenWithoutReturningToSource(){var p=new ServerPort();var w=new BottleFillWorkflow(p);w.startBatched(request(3),0,0,3);drive(w,300);assertEquals(State.COMPLETE,w.state(),w.reason());assertEquals(3,p.stores);assertEquals(4,p.opens);assertEquals(3,p.sourceApproaches);assertEquals(3,w.completed());}
    @Test void failedPredictedStoreKeepsAllConvertedWaterAndSendsNoSecondStore(){var p=new ServerPort();p.acceptStore=false;var w=new BottleFillWorkflow(p);w.startBatched(request(3),0,0,3);drive(w,300);assertEquals(State.FAILED,w.state(),w.reason());assertEquals(3,p.uses);assertEquals(1,p.stores);assertEquals(0,w.completed());assertEquals(3,p.inventory.stream().filter(BottleFillWorkflowTest.WATER::matches).count());}
    @Test void cancelDuringCollectionKeepsAcceptedWaterWithoutDrainingIt(){var p=new ServerPort();var w=new BottleFillWorkflow(p);w.startBatched(request(3),0,0,3);for(int t=1;t<30&&p.uses<1;t++)w.tick(t);w.cancel();drive(w,300);assertEquals(State.CANCELLED,w.state(),w.reason());assertEquals(1,p.uses);assertEquals(0,p.stores);assertEquals(1,p.inventory.stream().filter(BottleFillWorkflowTest.WATER::matches).count());assertEquals(2,p.selected);}
    @Test void lastGlassConvertsInHandAndIsNotLost(){var p=new ServerPort();p.inventory.set(0,new Stack(BottleFillWorkflowTest.GLASS,1,false));var w=new BottleFillWorkflow(p);w.startBatched(request(1),0,0,3);drive(w,300);assertEquals(State.COMPLETE,w.state(),w.reason());assertTrue(p.inventory.get(0).empty());assertEquals(1,w.completed());assertEquals(2,p.selected);}
    @Test void missingFillReceiptGetsFreshCleanupLedgerButNoConversionCreditOrRetry(){var p=new ServerPort();p.nativeFill=false;var w=new BottleFillWorkflow(p);w.startBatched(request(3),0,0,3);drive(w,1200);assertEquals(State.FAILED,w.state(),w.reason());assertEquals(1,p.uses);assertEquals(0,p.stores);assertEquals(0,w.completed());assertEquals(2,p.selected);assertEquals(1,p.inventory.stream().filter(BottleFillWorkflowTest.WATER::matches).count());}
    @Test void legacyPreparedModeRetainsItsSeparatePerPotContract(){var p=new ServerPort();var w=new BottleFillWorkflow(p);w.start(request(2),0,0);for(int t=1;t<30&&w.state()!=State.CHEST;t++)w.tick(t);assertEquals(State.CHEST,w.state());assertEquals(1,p.uses);}
}
